package ai.graine.inapp

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * EVERY EVENT HERE WAS MADE BY THE TYPESCRIPT THAT DEFINES THE ROWS.
 *
 * sdk/contract/call-analytics.json is generated by
 * sdk/contract/generate-call-analytics.mjs from sdk/inapp/protocol.ts (CALL
 * ANALYTICS ROWS v1): the rows, each row's keys and types, the enums, the
 * ceilings, and cases — an input and the exact event callAnalyticsEvent makes
 * of it. Android's builder (CallAnalytics.event) must make the same event, byte
 * for byte; the iOS engine and the server read the same file.
 */
class CallAnalyticsVectorsTest {
    private val text: String by lazy {
        var dir: File? = File("").absoluteFile
        while (dir != null && !File(dir, "sdk/contract/call-analytics.json").exists() && !File(dir, "contract/call-analytics.json").exists()) {
            dir = dir.parentFile
        }
        val f = listOf(File(dir, "sdk/contract/call-analytics.json"), File(dir, "contract/call-analytics.json")).firstOrNull { it.exists() }
            ?: error("sdk/contract/call-analytics.json missing — run sdk/contract/generate-call-analytics.mjs")
        f.readText()
    }

    /** Key order matters — it is in the event's bytes — and org.json's JVM build does not keep it. */
    @Suppress("UNCHECKED_CAST")
    private val vectors: Map<String, Any?> by lazy { OrderedJson.parse(text) as Map<String, Any?> }

    @Suppress("UNCHECKED_CAST")
    private fun list(v: Any?): List<Any?> = v as List<Any?>
    @Suppress("UNCHECKED_CAST")
    private fun obj(v: Any?): Map<String, Any?> = v as Map<String, Any?>

    @Test fun everyCaseMakesTheTypeScriptsEventByteForByte() {
        val cases = list(vectors["cases"]).map(::obj)
        assertEquals(17, cases.size)
        for (c in cases) {
            val title = c["name"] as String
            val input = obj(c["input"])
            val got = CallAnalytics.event(input["name"] as String, input["data"]?.let(::obj))
            val expect = c["event"]
            if (expect == null) assertNull(title, got) else assertEquals(title, JsJson.stringify(expect), got)
        }
    }

    /**
     * "Byte for byte" above means JavaScript's bytes: the file is
     * JSON.stringify(contract, null, 1), so without its white space it is
     * JSON.stringify(contract) — and the test's writer, given the file's own
     * parse, must write exactly that.
     */
    @Test fun theTestsWriterWritesWhatJavaScriptWrote() {
        assertEquals(minify(text), JsJson.stringify(vectors))
    }

    @Test fun theRowsTheirKeysAndTypesTheEnumsAndTheCeilingsAreTheContracts() {
        assertEquals((vectors["version"] as Number).toInt(), CallAnalytics.VERSION)
        assertEquals((vectors["max_keys"] as Number).toInt(), CallAnalytics.MAX_KEYS)
        val rows = obj(vectors["rows"])
        assertEquals("the rows, in order", rows.keys.toList(), CallAnalytics.ROWS.keys.toList())
        for ((name, r) in rows) {
            val keys = list(obj(r)["keys"])
            val types = obj(obj(r)["types"])
            assertEquals(name, keys, CallAnalytics.ROWS.getValue(name).map { it.first })
            assertEquals(name, keys.map { types[it] }, CallAnalytics.ROWS.getValue(name).map { it.second })
            assertTrue("$name: at most ${CallAnalytics.MAX_KEYS} keys", keys.size <= CallAnalytics.MAX_KEYS)
        }
        assertEquals("connect names all twelve", CallAnalytics.MAX_KEYS, CallAnalytics.ROWS.getValue(CallAnalytics.CONNECT).size)
        val enums = obj(vectors["enums"])
        assertEquals(enums.keys.toList(), CallAnalytics.ENUMS.keys.toList())
        for ((name, values) in enums) assertEquals(name, values, CallAnalytics.ENUMS.getValue(name))
        assertEquals(obj(vectors["limits"]).mapValues { (it.value as Number).toLong() }, CallAnalytics.LIMITS)
    }

    /** The edges past the file's cases, each answer made by the TypeScript (callAnalyticsEvent, node, 19 Oct). */
    @Test fun theEdgesAreTheTypeScriptsToo() {
        fun data(name: String, input: Map<String, Any?>): String = CallAnalytics.event(name, input)!!.substringAfter("\"data\":").dropLast(1)
        fun detail(name: String, input: Map<String, Any?>): String = CallAnalytics.event(name, input)!!.substringAfter("\"detail\":\"").substringBefore('"')
        // A codec in any spelling, written the SDP way; anything else left out.
        assertEquals("{\"codec\":\"opus\"}", data("voice", mapOf("codec" to "OPUS")))
        assertEquals("{\"codec\":\"opus/48000\"}", data("voice", mapOf("codec" to "  audio/opus/48000  ")))
        assertEquals("{\"codec\":\"PCMU/8000\"}", data("voice", mapOf("codec" to "audio/PCMU/8000/1")))
        assertEquals("{\"codec\":\"G722/16000\"}", data("voice", mapOf("codec" to "AUDIO/g722/16000")))
        assertEquals("{\"codec\":\"iLBC\"}", data("voice", mapOf("codec" to "ilbc")))
        assertEquals("{\"codec\":\"PCMA\"}", data("voice", mapOf("codec" to "﻿pcma　")))
        assertEquals("{\"codec\":\"L16/24000\"}", data("voice", mapOf("codec" to "l16/24000")))
        assertEquals("{\"codec\":\"opus\"}", data("voice", mapOf("codec" to "opus\n")))
        for (bad in listOf("opus/480", "opus/48000/123", "opus\u0085", 42)) assertEquals("$bad", "{}", data("voice", mapOf("codec" to bad)))
        // Percentages: two decimals, half up, held at 100; a detail's one decimal from them.
        assertEquals("{\"duration_s\":86400,\"loss_pct\":0.05}", data("quality", mapOf("duration_s" to 86400.4, "loss_pct" to 0.05)))
        assertEquals("86400s · loss 0.1%", detail("quality", mapOf("duration_s" to 86400.4, "loss_pct" to 0.05)))
        assertEquals("{\"duration_s\":86400,\"loss_pct\":0.01,\"jitter_avg_ms\":0}", data("quality", mapOf("duration_s" to 90000, "loss_pct" to 0.005, "jitter_avg_ms" to 0)))
        assertEquals("86400s · loss 0.0% · jitter 0 ms", detail("quality", mapOf("duration_s" to 90000, "loss_pct" to 0.005, "jitter_avg_ms" to 0)))
        assertEquals("{\"loss_pct\":0}", data("quality", mapOf("loss_pct" to 0.004)))
        assertEquals("{\"loss_pct\":12.35}", data("quality", mapOf("loss_pct" to 12.345)))
        assertEquals("loss 12.4%", detail("quality", mapOf("loss_pct" to 12.345)))
        assertEquals("{\"loss_pct\":0.5,\"rtt_avg_ms\":600000}", data("quality", mapOf("loss_pct" to 0.5, "rtt_avg_ms" to 600000.6)))
        assertEquals("{\"loss_pct\":100}", data("quality", mapOf("loss_pct" to 99.996)))
        assertEquals("loss 100.0%", detail("quality", mapOf("loss_pct" to 99.996)))
        assertEquals("call quality", detail("quality", emptyMap()))
        // Seconds in a detail: tenths = floor((ms + 50) / 100).
        assertEquals("recovered after 0.0s", detail("recovery", mapOf("after_ms" to 49)))
        assertEquals("socket replaced after 0.1s", detail("recovery", mapOf("what" to "socket_replaced", "after_ms" to 50)))
        assertEquals("redial after 0.9s", detail("recovery", mapOf("what" to "redial", "after_ms" to 949.4)))
        assertEquals("redial after 1.0s", detail("recovery", mapOf("what" to "redial", "after_ms" to 950)))
        // Half up, a count held at 20, a negative zero is zero.
        assertEquals("{\"total_ms\":1,\"redials\":20,\"prepared_age_s\":0}", data("connect", mapOf("redials" to 20.5, "prepared_age_s" to -0.0, "total_ms" to 0.49999999999999994)))
        assertEquals("connected · 0.0s", detail("connect", mapOf("redials" to 20.5, "prepared_age_s" to -0.0, "total_ms" to 0.49999999999999994)))
        assertEquals("cold (setup 0.0s)", detail("connect", mapOf("warm" to false, "setup_ms" to 10)))
        assertEquals("connected (answer 1.0s)", detail("connect", mapOf("dial_ms" to 1049)))
        // NaN, infinity and a numeric string are left out; a Float and a Long are numbers like any other.
        val kotlinNumbers = mapOf("total_ms" to 2.5f, "setup_ms" to 5_000_000_000L, "dial_ms" to Double.NaN, "mint_ms" to Double.POSITIVE_INFINITY, "gather_ms" to "12")
        assertEquals("{\"total_ms\":3,\"setup_ms\":600000}", data("connect", kotlinNumbers))
        assertEquals("connected · 0.0s (setup 600.0s)", detail("connect", kotlinNumbers))
        assertEquals("fallback: dashboard", detail("transport", mapOf("requested" to "rtc", "fallback_reason" to "dashboard")))
        assertEquals("transport", detail("transport", emptyMap()))
        assertEquals("no audio path", detail("media", emptyMap()))
        assertEquals("no audio path (ice_failed)", detail("media", mapOf("reason" to "ice_failed", "transport" to "ws")))
        assertEquals("agent's voice 0.0s after the answer", detail("voice", mapOf("answer_to_voice_ms" to 1, "first_audio_ms" to 2, "candidate" to "host")))
        assertEquals("agent's voice heard", detail("voice", emptyMap()))
        // No input at all: the row with nothing in it.
        assertEquals("{\"name\":\"media\",\"detail\":\"no audio path\",\"quiet\":true,\"telemetry\":true,\"data\":{}}", CallAnalytics.event("media", null))
    }

    @Test fun aFrameIsTheEventInTheAppEventFrame() {
        val event = CallAnalytics.event("recovery", mapOf("what" to "redial", "after_ms" to 1210))!!
        assertEquals("{\"type\":\"app_event\",\"event\":$event}", CallAnalytics.frame("recovery", mapOf("what" to "redial", "after_ms" to 1210)))
        assertNull("a name that is not a row is never sent", CallAnalytics.frame("network", mapOf("online" to false)))
    }

    /** The JSON without the white space between its tokens. */
    private fun minify(s: String): String {
        val sb = StringBuilder(s.length)
        var inString = false
        var i = 0
        while (i < s.length) {
            val c = s[i]
            when {
                inString && c == '\\' -> { sb.append(c).append(s[i + 1]); i += 2; continue }
                inString -> { sb.append(c); if (c == '"') inString = false }
                c == '"' -> { sb.append(c); inString = true }
                !c.isWhitespace() -> sb.append(c)
            }
            i++
        }
        return sb.toString()
    }
}

/**
 * JSON.stringify, for what OrderedJson reads: keys in their order, a whole
 * number without a fraction, any other number as the shortest decimal (what
 * Kotlin's Double.toString writes for the file's values — the self-check above
 * holds it to that), strings as Json.quote writes them. Test-only.
 */
internal object JsJson {
    fun stringify(v: Any?): String = StringBuilder().also { write(it, v) }.toString()

    private fun write(sb: StringBuilder, v: Any?) {
        when (v) {
            null -> sb.append("null")
            is String -> Json.quote(sb, v)
            is Boolean, is Int, is Long -> sb.append(v)
            is Double -> sb.append(if (v == Math.floor(v) && Math.abs(v) < 1e15) v.toLong().toString() else v.toString())
            is Map<*, *> -> {
                sb.append('{')
                var first = true
                for ((k, x) in v) {
                    if (!first) sb.append(',')
                    first = false
                    Json.quote(sb, k as String)
                    sb.append(':')
                    write(sb, x)
                }
                sb.append('}')
            }
            is List<*> -> {
                sb.append('[')
                v.forEachIndexed { i, x -> if (i > 0) sb.append(','); write(sb, x) }
                sb.append(']')
            }
            else -> error("not JSON: $v")
        }
    }
}
